// 1. Publish Post
POST /api/v1/posts
Request:
{
  "content": "Launching our new distributed caching layer today!",
  "media_ids": ["med_8812"]
}
Response (201 Created):
{
  "post_id": "718293910293847102",
  "author_id": "440192",
  "fanout_mode": "PUSH_ASYNC",
  "created_at": "2026-09-30T16:25:00Z"
}

// 2. Fetch Cursor-Paginated Home Timeline
GET /api/v1/feed?cursor=718293910293847102&limit=20
Response (200 OK):
{
  "items": [
    {
      "post_id": "718293910293847055",
      "author": { "user_id": "9910", "handle": "@system_arch" },
      "content": "Hybrid push-pull avoids celebrity write amplification.",
      "like_count": 412
    }
  ],
  "next_cursor": "718293800112233445"
}

// ---------------------------------------------------------------------------
// Core Storage Entities & Schema Definitions
// ---------------------------------------------------------------------------
ENTITY users (PostgreSQL + Redis Cache) {
  [PK ] user_id                BIGINT
  [IDX] handle                 VARCHAR(64)
        follower_count         INT
  [IDX] is_celebrity           BOOLEAN (>= 10k)
        created_at             TIMESTAMPTZ
}

ENTITY follows_graph (Cassandra / Social Graph DB) {
  [PK ] follower_id            BIGINT (Partition)
  [PK ] followee_id            BIGINT (Clustering)
        is_celeb_edge          BOOLEAN
        created_at             TIMESTAMPTZ
}

ENTITY posts (Cassandra + Redis Post Cache) {
  [PK ] post_id                BIGINT (Snowflake)
  [FK ] author_id              BIGINT
        content                VARCHAR(2000)
        media_urls             ARRAY<TEXT>
  [IDX] created_at             TIMESTAMPTZ
}

// Relationships: users --(1 : N (social graph edges))--> follows_graph --(1 : N (publishes posts))--> posts
